CREATE TYPE "order_status" AS ENUM ('draft','awaiting_payment','confirmed','assigned','collection_in_progress','collected','lab_processing','results_ready','completed','cancelled','exception');
CREATE TYPE "specimen_status" AS ENUM ('planned','collected','packaged','in_transit','lab_received','accepted','rejected','lost','damaged');
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "identity_subject" varchar(255) NOT NULL UNIQUE, "email" varchar(320), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "patients" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "display_name" varchar(200) NOT NULL, "date_of_birth" date, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "patient_relationships" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL REFERENCES "users"("id"), "patient_id" uuid NOT NULL REFERENCES "patients"("id"), "relationship" varchar(40) NOT NULL, "can_book" boolean NOT NULL DEFAULT false, "can_view_results" boolean NOT NULL DEFAULT false, "verified_at" timestamptz, "revoked_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "relationship_patient_idx" ON "patient_relationships"("patient_id");
CREATE TABLE "staff" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL UNIQUE REFERENCES "users"("id"), "role" varchar(40) NOT NULL, "active" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "laboratories" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(200) NOT NULL, "active" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "tests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "code" varchar(64) NOT NULL UNIQUE, "name" varchar(200) NOT NULL, "specimen_type" varchar(80) NOT NULL, "active" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "lab_offerings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "lab_id" uuid NOT NULL REFERENCES "laboratories"("id"), "test_id" uuid NOT NULL REFERENCES "tests"("id"), "price_kobo" integer NOT NULL CHECK ("price_kobo" >= 0), "turnaround_hours" integer NOT NULL CHECK ("turnaround_hours" > 0), "active" boolean NOT NULL DEFAULT false, CONSTRAINT "lab_test_unique" UNIQUE ("lab_id","test_id"));
CREATE TABLE "orders" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "patient_id" uuid NOT NULL REFERENCES "patients"("id"), "booked_by" uuid NOT NULL REFERENCES "users"("id"), "lab_id" uuid NOT NULL REFERENCES "laboratories"("id"), "status" order_status NOT NULL DEFAULT 'draft', "tier" varchar(20) NOT NULL CHECK ("tier" IN ('regular','premium')), "currency" varchar(3) NOT NULL DEFAULT 'NGN', "total_kobo" integer NOT NULL CHECK ("total_kobo" >= 0), "collection_window_start" timestamptz, "collection_window_end" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "order_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "order_id" uuid NOT NULL REFERENCES "orders"("id"), "test_id" uuid NOT NULL REFERENCES "tests"("id"), "price_kobo" integer NOT NULL CHECK ("price_kobo" >= 0));
CREATE TABLE "specimens" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "order_id" uuid NOT NULL REFERENCES "orders"("id"), "barcode" varchar(100) NOT NULL UNIQUE, "status" specimen_status NOT NULL DEFAULT 'planned', "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "custody_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "specimen_id" uuid NOT NULL REFERENCES "specimens"("id"), "actor_id" uuid NOT NULL REFERENCES "users"("id"), "event_type" varchar(64) NOT NULL, "payload" jsonb NOT NULL DEFAULT '{}'::jsonb, "occurred_at" timestamptz NOT NULL, "recorded_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "custody_specimen_idx" ON "custody_events"("specimen_id");
CREATE TABLE "results" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "order_id" uuid NOT NULL REFERENCES "orders"("id"), "patient_id" uuid NOT NULL REFERENCES "patients"("id"), "object_key" text NOT NULL, "released_at" timestamptz, "released_by" uuid REFERENCES "users"("id"), "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "payments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "order_id" uuid NOT NULL REFERENCES "orders"("id"), "provider_reference" varchar(200) NOT NULL UNIQUE, "amount_kobo" integer NOT NULL CHECK ("amount_kobo" >= 0), "status" varchar(32) NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "ledger_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "transaction_id" uuid NOT NULL, "account" varchar(80) NOT NULL, "amount_kobo" integer NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "ledger_transaction_idx" ON "ledger_entries"("transaction_id");
CREATE TABLE "outbox" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "event_type" varchar(120) NOT NULL, "payload" jsonb NOT NULL, "attempts" integer NOT NULL DEFAULT 0, "processed_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "audit_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "actor_id" uuid REFERENCES "users"("id"), "action" varchar(120) NOT NULL, "resource_type" varchar(80) NOT NULL, "resource_id" uuid, "occurred_at" timestamptz NOT NULL DEFAULT now(), "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb);
